import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.D_V8FuNN.js";var i=JSON.parse(`{"title":"Save as PDF","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/save-as-pdf.md","filePath":"documentation/field-types/save-as-pdf.md","lastUpdated":1758109585000}`),a={name:`documentation/field-types/save-as-pdf.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="save-as-pdf" tabindex="-1">Save as PDF <a class="header-anchor" href="#save-as-pdf" aria-label="Permalink to “Save as PDF”">​</a></h1><p>Save web pages as PDF files using the browser&#39;s print functionality. Configure PDF generation settings, file naming, and save options for automated document creation.</p><h2 id="save-as-pdf-field-options" tabindex="-1">📋 Field Options <a class="header-anchor" href="#save-as-pdf-field-options" aria-label="Permalink to “📋 Field Options”">​</a></h2><table tabindex="0"><thead><tr><th>Field Options</th><th>Required</th><th>Description</th><th>Example Values</th></tr></thead><tbody><tr><td><strong>Press Ctrl + P</strong></td><td>No</td><td>Automatically trigger print dialog</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Press Ctrl + S</strong></td><td>No</td><td>Use Ctrl+S shortcut for saving</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Set the image path to identify the print preview window.</strong></td><td>No</td><td>Custom image for print preview window detection</td><td><code>/path/to/image.png</code></td></tr><tr><td><strong>Set the image path to identify the print button.</strong></td><td>No</td><td>Custom image to identify and click print button</td><td><code>/path/to/print_btn.png</code></td></tr><tr><td><strong>Set delay time after opening print window</strong></td><td>No</td><td>Wait time after print dialog opens</td><td><code>1000</code>, <code>2000</code> (milliseconds)</td></tr><tr><td><strong>Set delay time after pdf saved.</strong></td><td>No</td><td>Wait time after PDF is saved</td><td><code>1000</code>, <code>2000</code> (milliseconds)</td></tr><tr><td><strong>Wait until the print page title matches?</strong></td><td>No</td><td>Regex pattern to wait for matching print page title</td><td><code>.*\\.pdf$</code>, <code>(?i)^Application.*</code></td></tr><tr><td><strong>If file already exists in the save location then replace it</strong></td><td>No</td><td>Overwrite existing files with same name</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Set the <code>confirm replace save as browser window</code> title name</strong></td><td>No</td><td>Set the confirm replace save as browser window title name</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Set the <code>save as browser window</code> title name</strong></td><td>No</td><td>Set the save as browser window title name</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Direct Save Page to PDF (Firefox only)</strong></td><td>No</td><td>Direct PDF save without print dialog</td><td>Toggle ON/OFF</td></tr><tr><td><strong>Field Value</strong></td><td>No</td><td>Custom filename for PDF</td><td><code>document.pdf</code>, <code>report_{$name$}.pdf</code></td></tr></tbody></table><h2 id="save-as-pdf-configuration" tabindex="-1">⚙️ Configuration <a class="header-anchor" href="#save-as-pdf-configuration" aria-label="Permalink to “⚙️ Configuration”">​</a></h2><h3 id="print-options" tabindex="-1">🖨️ Print Options <a class="header-anchor" href="#print-options" aria-label="Permalink to “🖨️ Print Options”">​</a></h3><h4 id="press-ctrl-p" tabindex="-1">📌 Press Ctrl + P <a class="header-anchor" href="#press-ctrl-p" aria-label="Permalink to “📌 Press Ctrl + P”">​</a></h4><p><strong>Purpose:</strong> Automatically trigger the print dialog without manual keyboard input.</p><p><strong>How it works:</strong></p><ul><li>If you want to save the page through <code>Ctrl + P</code>, turn on this option</li><li>No need to manually press <code>Ctrl + P</code> buttons</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>If your file/PDF is downloaded after clicking any button, provide the selector query of that button in field selector query.</p></div><hr><h4 id="set-the-image-path-to-identify-the-print-preview-window" tabindex="-1">📌 Set the image path to identify the print preview window. <a class="header-anchor" href="#set-the-image-path-to-identify-the-print-preview-window" aria-label="Permalink to “📌 Set the image path to identify the print preview window.”">​</a></h4><p><strong>Purpose:</strong> Use custom image to detect when print preview window is ready.</p><p><strong>How to configure:</strong></p><ol><li><strong>Save an image</strong> of the print preview window on your PC</li><li><strong>Provide the image path</strong> in this option</li><li><strong>Extension waits</strong> until the image is visible on screen</li></ol><p><strong>Image Requirements:</strong></p><ul><li>Clear screenshot of print preview window</li><li>Unique elements that identify the print dialog</li><li>Reasonable file size for quick processing</li></ul><p><strong>Example Image:</strong></p><img src="/image/print-window-01.png" alt="Print Window Detection"><div class="warning custom-block"><p class="custom-block-title">Important</p><ul><li>If you are using the same image to other pc so maybe the image is not working properly.</li><li>So you can take the image from the same pc where you are using the extension.</li><li>If you resize the browser window so maybe the image is not working properly.</li></ul></div><hr><h4 id="set-the-image-path-to-identify-the-print-button" tabindex="-1">📌 Set the image path to identify the print button. <a class="header-anchor" href="#set-the-image-path-to-identify-the-print-button" aria-label="Permalink to “📌 Set the image path to identify the print button.”">​</a></h4><p><strong>Purpose:</strong> Use custom image to locate and click the print button in the print window.</p><p><strong>How to configure:</strong></p><ol><li><strong>Save an image</strong> of the print button on your PC</li><li><strong>Provide the image path</strong> in this option</li><li><strong>Extension waits</strong> until the button image is detected and clicked</li></ol><hr><h4 id="set-delay-time-after-opening-print-window" tabindex="-1">📌 Set delay time after opening print window <a class="header-anchor" href="#set-delay-time-after-opening-print-window" aria-label="Permalink to “📌 Set delay time after opening print window”">​</a></h4><p><strong>Purpose:</strong> Add wait time between opening print window and saving the PDF.</p><p><strong>Configuration:</strong></p><ul><li><strong>Delay time</strong> in milliseconds</li><li><strong>Recommended values:</strong> 3000-5000ms</li><li><strong>Adjust based on</strong> page complexity and loading time</li></ul><hr><h4 id="set-delay-time-after-pdf-saved" tabindex="-1">📌 Set delay time after pdf saved. <a class="header-anchor" href="#set-delay-time-after-pdf-saved" aria-label="Permalink to “📌 Set delay time after pdf saved.”">​</a></h4><p><strong>Purpose:</strong> Add wait time after the PDF file has been saved before proceeding further.</p><p><strong>Configuration:</strong></p><ul><li><strong>Delay time</strong> in milliseconds (e.g. <code>2000</code>)</li></ul><hr><h4 id="wait-until-the-print-page-title-matches" tabindex="-1">📌 Wait until the print page title matches? <a class="header-anchor" href="#wait-until-the-print-page-title-matches" aria-label="Permalink to “📌 Wait until the print page title matches?”">​</a></h4><p><strong>Purpose:</strong> Wait until the browser page or print title matches a specified regex pattern before saving.</p><p>Here are some useful regex examples for matching browser page titles.</p><table tabindex="0"><thead><tr><th>Regex</th><th>Matches</th><th>Description</th></tr></thead><tbody><tr><td><code>.*</code></td><td>Any title</td><td>Match every page title.</td></tr><tr><td><code>(?i).*</code></td><td>Any title</td><td>Match every title (case-insensitive).</td></tr><tr><td><code>^My Page$</code></td><td><code>My Page</code></td><td>Exact title match.</td></tr><tr><td><code>(?i)^My Page$</code></td><td><code>my page</code>, <code>MY PAGE</code></td><td>Exact title, ignore case.</td></tr><tr><td><code>Invoice</code></td><td><code>Invoice 123</code></td><td>Title contains <code>Invoice</code>.</td></tr><tr><td><code>(?i)Invoice</code></td><td><code>invoice</code>, <code>INVOICE</code></td><td>Contains <code>Invoice</code>, ignore case.</td></tr><tr><td><code>^Invoice</code></td><td><code>Invoice #123</code></td><td>Title starts with <code>Invoice</code>.</td></tr><tr><td><code>Invoice$</code></td><td><code>Final Invoice</code></td><td>Title ends with <code>Invoice</code>.</td></tr><tr><td><code>(?i)\\.pdf$</code></td><td><code>form.pdf</code></td><td>Ends with <code>.pdf</code> (ignore case).</td></tr><tr><td><code>(?i)^.*\\.pdf$</code></td><td><code>Application.pdf</code></td><td>Any PDF filename.</td></tr><tr><td><code>(?i)^Application\\.pdf$</code></td><td><code>Application.pdf</code></td><td>Exact PDF filename.</td></tr><tr><td><code>(?i)^Application.*\\.pdf$</code></td><td><code>Application_v2.pdf</code></td><td>PDF beginning with <code>Application</code>.</td></tr><tr><td><code>(?i)Application.*</code></td><td><code>Application Form - Chrome</code></td><td>Title contains <code>Application</code> followed by anything.</td></tr><tr><td><code>(?i)^.*Google Chrome$</code></td><td><code>form.pdf - Google Chrome</code></td><td>Any Chrome window.</td></tr><tr><td><code>(?i)^.*Microsoft Edge$</code></td><td><code>form.pdf - Microsoft Edge</code></td><td>Any Edge window.</td></tr><tr><td><code>(?i)^.*(Chrome|Edge)$</code></td><td>Chrome or Edge</td><td>Match either browser.</td></tr><tr><td><code>(?i)^.*\\.pdf - Google Chrome$</code></td><td><code>abc.pdf - Google Chrome</code></td><td>Any PDF opened in Chrome.</td></tr><tr><td><code>(?i)^.*\\.pdf - Microsoft Edge$</code></td><td><code>abc.pdf - Microsoft Edge</code></td><td>Any PDF opened in Edge.</td></tr><tr><td><code>(?i)^.*.(pdf|docx)$</code></td><td><code>a.pdf</code>, <code>b.docx</code></td><td>Match PDF or DOCX.</td></tr><tr><td><code>(?i)success|completed</code></td><td><code>Completed Successfully</code></td><td>Contains either <code>success</code> or <code>completed</code>.</td></tr><tr><td><code>(?i)(login|signin)</code></td><td><code>Login</code>, <code>Sign In</code></td><td>Match either word.</td></tr><tr><td><code>^[0-9]+$</code></td><td><code>12345</code></td><td>Numbers only.</td></tr><tr><td><code>^[A-Za-z]+$</code></td><td><code>Welcome</code></td><td>Letters only.</td></tr><tr><td><code>^[A-Za-z0-9 _-]+$</code></td><td><code>Invoice_2026-01</code></td><td>Letters, numbers, spaces, <code>_</code> and <code>-</code>.</td></tr></tbody></table><h5 id="regex-symbols" tabindex="-1">Regex symbols <a class="header-anchor" href="#regex-symbols" aria-label="Permalink to “Regex symbols”">​</a></h5><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>^</code></td><td>Start of text</td><td><code>^Invoice</code></td></tr><tr><td><code>$</code></td><td>End of text</td><td><code>\\.pdf$</code></td></tr><tr><td><code>.</code></td><td>Any single character</td><td><code>a.c</code></td></tr><tr><td><code>.*</code></td><td>Any number of any characters</td><td><code>Invoice.*</code></td></tr><tr><td><code>+</code></td><td>One or more</td><td><code>[0-9]+</code></td></tr><tr><td><code>?</code></td><td>Zero or one</td><td><code>colou?r</code></td></tr><tr><td><code>\\.</code></td><td>Literal dot (<code>.</code>)</td><td><code>\\.pdf</code></td></tr><tr><td><code>\\d</code></td><td>Digit</td><td><code>\\d{4}</code></td></tr><tr><td><code>[abc]</code></td><td>One of the listed characters</td><td><code>[AB]</code></td></tr><tr><td><code>[A-Z]</code></td><td>Uppercase letter</td><td><code>[A-Z]{3}</code></td></tr><tr><td><code>[0-9]</code></td><td>Digit</td><td><code>[0-9]{6}</code></td></tr><tr><td><code>[^0-9]</code></td><td>Not a digit</td><td><code>[^0-9]+</code></td></tr><tr><td><code>(A|B)</code></td><td>A or B</td><td><code>(Chrome|Edge)</code></td></tr><tr><td><code>(?i)</code></td><td>Ignore case</td><td><code>(?i)\\.pdf$</code></td></tr></tbody></table><hr><h3 id="browser-specific-options" tabindex="-1">🌐 Browser-Specific Options <a class="header-anchor" href="#browser-specific-options" aria-label="Permalink to “🌐 Browser-Specific Options”">​</a></h3><h4 id="direct-save-page-to-pdf-firefox-only" tabindex="-1">📌 Direct Save Page to PDF (Firefox Only) <a class="header-anchor" href="#direct-save-page-to-pdf-firefox-only" aria-label="Permalink to “📌 Direct Save Page to PDF (Firefox Only)”">​</a></h4><p><strong>Purpose:</strong> Save PDF directly without print dialog (Firefox browser only).</p><p><strong>Benefits:</strong></p><ul><li>Faster PDF generation</li><li>No print dialog interaction</li><li>Streamlined automation process</li></ul><hr><h3 id="file-management-options" tabindex="-1">📁 File Management Options <a class="header-anchor" href="#file-management-options" aria-label="Permalink to “📁 File Management Options”">​</a></h3><h4 id="if-file-already-exists-then-replace-it" tabindex="-1">📌 If file already exists then replace it <a class="header-anchor" href="#if-file-already-exists-then-replace-it" aria-label="Permalink to “📌 If file already exists then replace it”">​</a></h4><p><strong>Purpose:</strong> Control behavior when a file with the same name already exists.</p><p><strong>Options:</strong></p><ul><li><strong>ON</strong> - Replace existing file with new content</li><li><strong>OFF</strong> - Browser will ask to replace the file</li></ul><hr><h4 id="press-ctrl-s" tabindex="-1">📌 Press Ctrl + S <a class="header-anchor" href="#press-ctrl-s" aria-label="Permalink to “📌 Press Ctrl + S”">​</a></h4><p><strong>Purpose:</strong> Use Ctrl+S keyboard shortcut for saving files.</p><p><strong>How it works:</strong></p><ul><li>Triggers browser&#39;s save dialog</li><li>Alternative to print-based PDF generation</li><li>Works with most browsers</li></ul><hr><h3 id="file-naming" tabindex="-1">📝 File Naming <a class="header-anchor" href="#file-naming" aria-label="Permalink to “📝 File Naming”">​</a></h3><h4 id="field-value" tabindex="-1">📌 Field Value <a class="header-anchor" href="#field-value" aria-label="Permalink to “📌 Field Value”">​</a></h4><p><strong>Purpose:</strong> Set custom filename for the generated PDF.</p><p><strong>Basic Usage:</strong></p><ul><li><strong>Static name:</strong> <code>document.pdf</code></li><li><strong>Dynamic name:</strong> <code>report_{$name$}.pdf</code></li><li><strong>Date-based:</strong> <code>invoice_{$date.today[yyyy-mm-dd]$}.pdf</code></li><li><strong>Unique filename:</strong> <code>document_{$date.today[x]$}.pdf</code></li></ul><p><strong>Variable Syntax:</strong></p><ul><li>Use <code>{$variable_name$}</code> format</li><li>Access form data and system variables</li><li>Create unique filenames automatically</li></ul><hr><h2 id="pdf-page-settings-firefox" tabindex="-1">🎯 PDF Page Settings (Firefox) <a class="header-anchor" href="#pdf-page-settings-firefox" aria-label="Permalink to “🎯 PDF Page Settings (Firefox)”">​</a></h2><p>Customize PDF page settings for optimal document formatting.</p><h3 id="customize-pdf-page-settings" tabindex="-1">📌 Customize PDF Page Settings <a class="header-anchor" href="#customize-pdf-page-settings" aria-label="Permalink to “📌 Customize PDF Page Settings”">​</a></h3><p><strong>Purpose:</strong> Configure page size, orientation, margins, and other PDF properties.</p><p><strong>API Reference:</strong> <a href="https://developer.mozilla.org/en-US/docs/Mozilla/Add-ons/WebExtensions/API/tabs/PageSettings" target="_blank" rel="noreferrer">PageSettings API</a></p><p><strong>Example Configuration:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>paperHeight=297,paperWidth=210,orientation=1,scaling=0.65,paperSizeUnit=1,shrinkToFit=true</span></span></code></pre></div><p><strong>Result:</strong> A4 landscape size page</p><table tabindex="0"><thead><tr><th>Property</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><strong>paperHeight</strong></td><td>297</td><td>A4 height in mm</td></tr><tr><td><strong>paperWidth</strong></td><td>210</td><td>A4 width in mm</td></tr><tr><td><strong>orientation</strong></td><td>1</td><td>0 = portrait, 1 = landscape</td></tr><tr><td><strong>scaling</strong></td><td>0.65</td><td>Content scaling factor (default: 1)</td></tr><tr><td><strong>paperSizeUnit</strong></td><td>1</td><td>0 = inches, 1 = millimeters</td></tr><tr><td><strong>shrinkToFit</strong></td><td>true</td><td>Shrink content to fit page width</td></tr></tbody></table><h2 id="browser-window-title" tabindex="-1">🌐 Browser Window Title <a class="header-anchor" href="#browser-window-title" aria-label="Permalink to “🌐 Browser Window Title”">​</a></h2><h3 id="set-browser-window-title" tabindex="-1">📌 Set the save as browser window title name <a class="header-anchor" href="#set-browser-window-title" aria-label="Permalink to “📌 Set the save as browser window title name”">​</a></h3><p><strong>Purpose:</strong> Customize browser window title during PDF save process.</p><p><strong>Use Cases:</strong></p><ul><li><strong>Multi-language support</strong> - Different titles for different languages</li><li><strong>Branding</strong> - Custom application names</li><li><strong>Identification</strong> - Distinguish between different save operations</li></ul><p><strong>Configuration:</strong></p><ul><li>Set different titles for different languages</li><li>Use variables for dynamic titles</li><li>Match your application&#39;s branding</li></ul><hr><h3 id="set-confirm-replace-save-as-browser-window-title" tabindex="-1">📌 Set the confirm replace save as browser window title name <a class="header-anchor" href="#set-confirm-replace-save-as-browser-window-title" aria-label="Permalink to “📌 Set the confirm replace save as browser window title name”">​</a></h3><p><strong>Purpose:</strong> Customize browser window title during PDF save process.</p><p><strong>Use Cases:</strong></p><ul><li><strong>Multi-language support</strong> - Different titles for different languages</li><li><strong>Branding</strong> - Custom application names</li><li><strong>Identification</strong> - Distinguish between different save operations</li></ul><hr><h2 id="important-notes" tabindex="-1">⚠️ Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “⚠️ Important Notes”">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h3><p><a href="/documentation/program.html#download-and-install">Install Helper Program</a></p><ul><li><strong>Required</strong> before using this field type</li><li><strong>Download</strong> from extension settings</li><li><strong>Install</strong> the helper program on your system</li><li><strong>Verify</strong> installation before configuring PDF fields</li></ul><h2 id="troubleshooting" tabindex="-1">🔍 Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “🔍 Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Solution</th></tr></thead><tbody><tr><td><strong>PDF not generated</strong></td><td>Check helper program installation</td></tr><tr><td><strong>Print dialog not detected</strong></td><td>Adjust image path or disable detection</td></tr><tr><td><strong>File not saved</strong></td><td>Verify save location permissions</td></tr><tr><td><strong>Filename conflicts</strong></td><td>Use unique naming with variables</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Pro Tip</p><p>Use the <code>{$date.today[x]$}</code> variable in filenames to ensure unique file names every time.</p></div><div class="warning custom-block"><p class="custom-block-title">Important</p><p>Install the helper program before using this field type. The extension will not work without it.</p></div>`,99)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};